import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../supabaseClient';
import { useAuth } from '../../context/AuthContext';
import { CheckCircle, Calendar, User, Image as ImageIcon } from 'lucide-react';

const ArchitectPastProjects = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [pastProjects, setPastProjects] = useState([]);

  useEffect(() => {
    if (user?.id) {
      loadPastProjects();
    }
  }, [user?.id, loadPastProjects]);

  const loadPastProjects = useCallback(async () => {
    try {
      if (!user?.id) {
        setLoading(false);
        return;
      }

      console.log('Loading past projects for architect:', user.id);

      // Load completed projects
      const { data: projects, error: projectsError } = await supabase
        .from('projects')
        .select(`
          id,
          title,
          description,
          budget,
          deadline,
          status,
          created_at,
          updated_at,
          applications!inner (
            id,
            artist_id,
            quoted_price,
            delivery_status,
            delivery_files,
            delivery_approved_at,
            current_round,
            status,
            profiles!applications_artist_id_fkey (
              id,
              full_name,
              profile_photo
            )
          )
        `)
        .eq('architect_id', user.id)
        .eq('applications.status', 'completed')
        .order('updated_at', { ascending: false });

      if (projectsError) {
        console.error('Query error:', projectsError);
        throw projectsError;
      }

      console.log('Completed projects:', projects);

      // Map projects with artist info
      const mappedProjects = projects?.map(project => {
        const completedApp = project.applications[0]; // Get the completed application
        return {
          id: project.id,
          title: project.title,
          description: project.description,
          budget_min: project.budget,
          budget_max: project.budget_max,
          deadline: project.deadline,
          status: project.status,
          artist: completedApp.profiles,
          quoted_price: completedApp.quoted_price,
          delivery_count: completedApp.delivery_files?.length || 0,
          current_round: completedApp.current_round || 1,
          completed_at: completedApp.delivery_approved_at || project.updated_at,
          created_at: project.created_at
        };
      }) || [];

      console.log('Mapped past projects:', mappedProjects);
      setPastProjects(mappedProjects);
    } catch (error) {
      console.error('Error loading past projects:', error);
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  if (loading) {
    return (
      <div className="past-projects-container">
        <div className="loading-container">
          <p>Loading history...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="past-projects-container">
      <div className="page-header">
        <div>
          <h2 className="section-title">📊 Project History</h2>
          <p className="subtitle">Completed projects</p>
        </div>
        <div className="stats-summary">
          <div className="stat-card">
            <CheckCircle size={24} className="stat-icon" />
            <div className="stat-content">
              <div className="stat-value">{pastProjects.length}</div>
              <div className="stat-label">Completed Projects</div>
            </div>
          </div>
        </div>
      </div>

      {pastProjects.length === 0 ? (
        <div className="empty-state">
          <CheckCircle size={64} className="empty-icon" />
          <p className="empty-state-title">No completed projects yet</p>
          <p className="empty-state-text">
            Your completed projects will appear here
          </p>
        </div>
      ) : (
        <div className="projects-grid">
          {pastProjects.map(project => (
            <div key={project.id} className="past-project-card">
              <div className="project-header">
                <div className="status-badge completed">
                  <CheckCircle size={16} />
                  Completed
                </div>
                <div className="completion-date">
                  <Calendar size={14} />
                  {new Date(project.completed_at).toLocaleDateString('en-US')}
                </div>
              </div>

              <h3 className="project-title">{project.title}</h3>
              <p className="project-description">{project.description}</p>

              <div className="project-details">
                <div className="detail-row">
                  <User size={16} />
                  <span className="detail-label">Artist:</span>
                  <span className="detail-value">{project.artist.full_name}</span>
                </div>
                <div className="detail-row">
                  <ImageIcon size={16} />
                  <span className="detail-label">Deliveries:</span>
                  <span className="detail-value">{project.delivery_count} round{project.delivery_count > 1 ? 's' : ''}</span>
                </div>
              </div>

              <button
                onClick={() => navigate(`/dashboard/architect/project/${project.id}`)}
                className="btn-view-details"
              >
                View Details and Renders
              </button>
            </div>
          ))}
        </div>
      )}

      <style jsx>{`
        .past-projects-container {
          padding: 2rem;
          max-width: 1400px;
          margin: 0 auto;
        }

        .loading-container {
          display: flex;
          justify-content: center;
          align-items: center;
          min-height: 400px;
          color: #666;
        }

        .page-header {
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
          margin-bottom: 2rem;
          gap: 2rem;
          flex-wrap: wrap;
        }

        .section-title {
          font-size: 2rem;
          font-weight: 700;
          color: #1a1a1a;
          margin: 0 0 0.5rem 0;
        }

        .subtitle {
          color: #666;
          margin: 0;
        }

        .stats-summary {
          display: flex;
          gap: 1rem;
        }

        .stat-card {
          display: flex;
          align-items: center;
          gap: 1rem;
          background: white;
          padding: 1.5rem;
          border-radius: 12px;
          box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
          min-width: 200px;
        }

        .stat-icon {
          color: #667eea;
        }

        .stat-content {
          display: flex;
          flex-direction: column;
        }

        .stat-value {
          font-size: 1.5rem;
          font-weight: 700;
          color: #1a1a1a;
          line-height: 1;
          margin-bottom: 0.25rem;
        }

        .stat-label {
          font-size: 0.875rem;
          color: #666;
        }

        .empty-state {
          text-align: center;
          padding: 4rem 2rem;
          background: #f8f9fa;
          border-radius: 12px;
          border: 2px dashed #dee2e6;
        }

        .empty-icon {
          color: #adb5bd;
          margin-bottom: 1rem;
        }

        .empty-state-title {
          font-size: 1.5rem;
          font-weight: 600;
          color: #495057;
          margin: 0 0 0.5rem 0;
        }

        .empty-state-text {
          color: #6c757d;
          margin: 0;
        }

        .projects-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
          gap: 1.5rem;
        }

        .past-project-card {
          background: white;
          border-radius: 12px;
          box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
          padding: 1.5rem;
          transition: transform 0.2s, box-shadow 0.2s;
          display: flex;
          flex-direction: column;
        }

        .past-project-card:hover {
          transform: translateY(-2px);
          box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
        }

        .project-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 1rem;
        }

        .status-badge {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          padding: 0.5rem 1rem;
          border-radius: 20px;
          font-size: 0.875rem;
          font-weight: 600;
        }

        .status-badge.completed {
          background-color: #d4edda;
          color: #155724;
        }

        .completion-date {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 0.875rem;
          color: #666;
        }

        .project-title {
          font-size: 1.25rem;
          font-weight: 600;
          color: #1a1a1a;
          margin: 0 0 0.75rem 0;
        }

        .project-description {
          color: #495057;
          margin: 0 0 1.5rem 0;
          line-height: 1.6;
          flex-grow: 1;
        }

        .project-details {
          display: flex;
          flex-direction: column;
          gap: 0.75rem;
          padding: 1rem;
          background: #f8f9fa;
          border-radius: 8px;
          margin-bottom: 1rem;
        }

        .detail-row {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 0.875rem;
        }

        .detail-row svg {
          color: #667eea;
          flex-shrink: 0;
        }

        .detail-label {
          color: #6c757d;
          min-width: 90px;
        }

        .detail-value {
          font-weight: 600;
          color: #1a1a1a;
        }

        .btn-view-details {
          width: 100%;
          padding: 0.75rem 1.5rem;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          border: none;
          border-radius: 8px;
          font-weight: 600;
          cursor: pointer;
          transition: all 0.2s;
        }

        .btn-view-details:hover {
          transform: translateY(-1px);
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
        }

        @media (max-width: 768px) {
          .past-projects-container {
            padding: 1rem;
          }

          .page-header {
            flex-direction: column;
          }

          .stats-summary {
            flex-direction: column;
            width: 100%;
          }

          .stat-card {
            width: 100%;
          }

          .projects-grid {
            grid-template-columns: 1fr;
          }
        }
      `}</style>
    </div>
  );
};

export default ArchitectPastProjects;
